(function(){"use strict";function iso(d){return d.toISOString().slice(0,10)}function init(form){var from=form.querySelector('[name="date_from"]');var to=form.querySelector('[name="date_to"]');var target=form.getAttribute("data-target")||"/ro/cars";if(!from||!to)return;var today=new Date;var tomorrow=new Date(today.getTime()+864e5);var inAWeek=new Date(today.getTime()+8*864e5);from.min=iso(today);to.min=iso(tomorrow);if(!from.value)from.value=iso(tomorrow);if(!to.value)to.value=iso(inAWeek);from.addEventListener("change",function(){if(!from.value)return;var next=new Date(from.value);next.setDate(next.getDate()+1);to.min=iso(next);if(to.value&&to.value<=from.value)to.value=iso(next)});form.addEventListener("submit",function(e){e.preventDefault();var url=target;var params=[];if(from.value)params.push("date_from="+encodeURIComponent(from.value));if(to.value)params.push("date_to="+encodeURIComponent(to.value));if(params.length)url+="?"+params.join("&");if(typeof window.gtag_report_conversion==="function")window.gtag_report_conversion();window.location.href=url})}function start(){var forms=document.querySelectorAll(".pr-quick-dates");for(var i=0;i<forms.length;i++)init(forms[i])}if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",start)}else{start()}})();